"""Painel da plataforma (app/admin/, Playwright, modo demonstração): KPIs e MRR, pagamentos com filtro e CSV, detalhe do negócio
(trocar plano, salvar dados, cartão, itens, clientes, menu, modelo), criar por e-mail e por planilha, aplicar modelo, exportações,
auditoria, trava de acesso (conta logada que não é superadmin).

Uso (a partir da raiz):  python tests/check-platform.py
Sai com código 1 se algo falhar.
"""
import asyncio, pathlib, sys
from playwright.async_api import async_playwright

ADMIN = pathlib.Path(__file__).resolve().parent.parent / "app" / "admin" / "index.html"
FAILS = []
try: sys.stdout.reconfigure(encoding="utf-8")
except Exception: pass


def check(name, ok, extra=""):
    print(("  ok    " if ok else "  FALHA ") + name + (f"   → {extra}" if (extra and not ok) else ""))
    if not ok: FAILS.append(name)


